use std::fs
use std::env

fn pad(n: int) -> string {
    let mut s = "${n}"
    while s.len() < 6 {
        s = " " + s
    }
    s
}

fn main() {
    let mut numbering = false
    let mut names: Vec<string> = []
    for a in env::args().skip(1) {
        if a == "-n" {
            numbering = true
        } else {
            names.push(a)
        }
    }
    let mut failed = false
    let mut counter: int = 0
    let mut texts: Vec<string> = []
    if names.len() == 0 {
        texts.push(fs::read_to_string("/dev/stdin").unwrap_or(""))
    } else {
        for name in names {
            match fs::read_to_string(name) {
                Ok(t) => texts.push(t),
                Err(_) => {
                    texts.push("cat: ${name}: No such file\n")
                    failed = true
                }
            }
        }
    }
    for t in texts {
        if numbering {
            for line in t.lines() {
                counter += 1
                println("${pad(counter)}\t${line}")
            }
        } else {
            print(t)
        }
    }
    if failed {
        std::process::exit(1)
    }
}
